        // ═════════════════════════ DBC metadata attributes ═════════════════════════

        // AdHoc custom attributes: carried into the generated code as constants attached to the field / pack.
        // They live inside the project interface (the agent expects every class in a project); the connections use
        // explicit pack lists, so they are never collected as packs.

        /** Start bit of the signal in the CAN frame, as written in the DBC (LSB for Intel, MSB for Motorola). */
        public class StartBitAttribute : Attribute { public StartBitAttribute(int bit) { } }

        /** Motorola byte order (DBC @0); absent means Intel / little-endian (@1). */
        public class BigEndianAttribute : Attribute { }

        /** Physical value = raw * factor + offset. */
        public class FactorAttribute : Attribute { public FactorAttribute(double factor) { } }

        /** Physical value = raw * factor + offset. */
        public class OffsetAttribute : Attribute { public OffsetAttribute(double offset) { } }

        /** Physical [min|max] declared in the DBC (a UI hint, not a wire constraint). */
        public class PhysRangeAttribute : Attribute { public PhysRangeAttribute(double min, double max) { } }

        /** Unit of the physical value. */
        public class UnitsAttribute : Attribute { public UnitsAttribute(string units) { } }

        /** This signal selects which multiplexed signals are present. */
        public class MultiplexorAttribute : Attribute { }

        /** Present only when the multiplexor carries this value. */
        public class MultiplexedAttribute : Attribute { public MultiplexedAttribute(long value) { } }

        /** GenSigStartValue: raw value at ECU start. */
        public class StartValueAttribute : Attribute { public StartValueAttribute(double value) { } public StartValueAttribute(string value) { } }

        /** GenMsgCycleTime: transmission period in milliseconds. */
        public class CycleTimeAttribute : Attribute { public CycleTimeAttribute(double ms) { } public CycleTimeAttribute(string ms) { } }

        /** Name of the enum listing the named raw values (used when the table does not cover the whole range). */
        public class ValueTableAttribute : Attribute { public ValueTableAttribute(string enumName) { } }

        /** Any other DBC attribute (BA_) of the message or signal. */
        [AttributeUsage(AttributeTargets.All, AllowMultiple = true)]
        public class AttrAttribute : Attribute { public AttrAttribute(string name, string value) { } }
    }
